<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import RenewalDialog from './RenewalDialog.vue';import type {RequestFn} from './media';import {traffic,date,states} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,initial?:string}>();
const rows=ref<Row[]>([]),selected=ref<Row|null>(null),usage=ref<Row|null>(null),devices=ref<Row[]>([]),clients=ref<Row[]>([]),links=ref<Record<string,Row>>({}),checks=ref<Record<string,Row>>({}),qr=ref(''),qrClient=ref(''),busy=ref(false),error=ref(''),notice=ref(''),client=ref('auto'),renewing=ref(false);
const emit=defineEmits<{payment:[order:Row]}>();
const offset=ref(0),total=ref(0);let generation=0;
const formats=computed(()=>[{id:'auto',name:'自动识别客户端（推荐）',note:'sing-box 扫码请选择专属格式'},...clients.value.filter(c=>c.id!=='auto')]);
const canRenew=computed(()=>usage.value&&['active','expired','exhausted'].includes(usage.value.state));

const inactive=computed(()=>!!usage.value?.state&&!['active','unknown'].includes(usage.value.state));
const query=(id:string,c='auto')=>'?service='+encodeURIComponent(id)+'&client='+encodeURIComponent(c);
function clearQR(){if(qr.value)URL.revokeObjectURL(qr.value);qr.value='';qrClient.value=''}
function clearLinks(){links.value={};checks.value={};clearQR()}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function list(){const d=await props.request('me/services?offset='+offset.value);rows.value=Array.isArray(d)?d:d.items;total.value=d.total??rows.value.length}
async function details(row:Row){const ticket=++generation,q=query(row.id);const s=await props.request('me/service'+q);if(ticket!==generation)return;usage.value=s.service;if(usage.value?.state){row.service_state=usage.value.state;const cached=rows.value.find(r=>r.id===row.id);if(cached)cached.service_state=usage.value.state}if(inactive.value){devices.value=[];clearLinks();return}const d=await props.request('me/devices'+q);if(ticket===generation)devices.value=Array.isArray(d)?d:d.items||[]}
async function open(row:Row){await act(async()=>{selected.value=row;usage.value=null;devices.value=[];clearLinks();await details(row);if(!inactive.value)await getLink(client.value)})}
async function getLink(c:string){if(!selected.value||inactive.value)return null;const id=selected.value.id,q=query(id,c);delete links.value[c];const checked=await props.request('me/subscription/check'+q);checks.value[c]=checked;if(!checked.ready)return null;const link=await props.request('me/subscription/share'+q);if(selected.value?.id!==id)return null;links.value[c]=link;return link}
async function reveal(c:string){await act(async()=>{await getLink(c)})}
async function copyLink(c:string){await act(async()=>{const d=await getLink(c);if(!d)return;try{await navigator.clipboard.writeText(d.url);notice.value='已复制此订单的 '+(clients.value.find(x=>x.id===c)?.name||'自动识别')+' 链接'}catch{notice.value='请选中此格式下方的链接手动复制'}})}
async function showQR(c:string){await act(async()=>{const d=await getLink(c);if(!d)return;const response=await fetch('/portal/v1/me/subscription/qr'+query(selected.value!.id,c),{credentials:'same-origin'});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'二维码暂不可用')}clearQR();qr.value=URL.createObjectURL(await response.blob());qrClient.value=c})}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void act(async()=>{await list();const d=await props.request('clients');clients.value=Array.isArray(d)?d:(d.clients||d.items||[]);let first=rows.value.find(r=>r.id===props.initial);if(!first&&props.initial){const d=await props.request('me/service?service='+encodeURIComponent(props.initial));if(!d.service)throw new Error('未找到该订单的订阅');first={...d.service,id:props.initial}}if(!props.initial)first=rows.value[0];if(first){selected.value=first;await details(first);if(!inactive.value)await getLink(client.value)}});timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void act(async()=>{await list();if(selected.value)await details(selected.value)})},30000)});onUnmounted(()=>{generation++;clearInterval(timer);clearQR()});
</script>
<template>
<div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>
<section class="panel"><div class="section-head"><div><h3>我的独立订阅</h3><p class="muted">新购套餐独立开通；续费延长所选订阅。选择订阅后，在下方切换客户端格式导入。</p></div></div>
<div class="service-grid"><article v-for="s in rows" :key="s.id" class="service-card" :class="{selected:selected?.id===s.id}"><div class="section-head"><h3>{{s.plan_name}}</h3><span class="badge" :class="s.service_state">{{states[s.service_state]||'待同步'}}</span></div><p>{{traffic(s.quota_bytes,s.quota_unit||'GB')}} / 月</p><small class="mono">订单 {{s.id}}</small><small>{{date(s.paid_at)}} 开通</small><span v-if="s.legacy_combined" class="badge">旧版合并权益</span><button class="service-open" :disabled="busy" @click="open(s)">{{selected?.id===s.id?'已选中 · 查看下方订阅':'查看此订阅'}} →</button></article></div>
<div class="actions pagination" v-if="total>25"><button :disabled="busy||offset===0" @click="act(async()=>{offset=Math.max(0,offset-25);await list()})">上一页</button><span>{{offset+1}}–{{Math.min(offset+25,total)}} / {{total}}</span><button :disabled="busy||offset+25>=total" @click="act(async()=>{offset+=25;await list()})">下一页</button></div><p v-if="!rows.length" class="empty">尚未开通服务。已付款订单需等待身份和节点同步就绪。</p></section>
<section v-if="selected" class="panel"><div class="section-head"><div><h3>{{selected.plan_name}} · {{selected.id.slice(0,8)}}</h3><small class="mono">订单 {{selected.id}}</small></div><div class="actions"><span class="badge">{{states[usage?.state]||'正在查询'}}</span><button class="primary" v-if="canRenew" :disabled="busy" @click="renewing=true">续费此订阅</button></div></div>
<div v-if="usage&&!inactive" class="metrics"><article><span>剩余流量</span><strong>{{traffic(usage.remaining_bytes,usage.quota_unit||'GB')}}</strong></article><article><span>已用 / 本期配额</span><strong>{{traffic(usage.used_bytes,usage.quota_unit||'GB')}}</strong><small>{{traffic(usage.quota_bytes,usage.quota_unit||'GB')}}</small></article><article><span>到期时间</span><strong class="date">{{date(usage.expires_at)}}</strong></article></div>
<div v-if="inactive" class="alert error" role="status">此订单服务{{states[usage?.state]||'已失效'}}。订阅链接已停止展示，请联系管理员；订单与付款记录保留。</div>
<template v-else><div class="section-head"><div><h3>导入订阅</h3><p class="muted">链接与二维码都属于此订阅。切换格式后，使用对应客户端导入。</p></div></div>
<label class="client-format">客户端订阅格式<select v-model="client" :disabled="busy" @change="act(async()=>{clearQR();await getLink(client)})"><option v-for="c in formats" :key="c.id" :value="c.id">{{c.name||c.label||c.id}}</option></select></label>
<div v-if="checks[client]&&!checks[client].ready" class="alert error">{{checks[client].reason||'此客户端暂没有可用节点'}}</div>
<div class="share-area"><div><label v-if="links[client]">{{formats.find(c=>c.id===client)?.name||client}} · 订阅链接<input aria-label="当前客户端订阅链接" :value="links[client].url" readonly @focus="($event.target as HTMLInputElement).select()"></label><div class="actions"><button class="primary" :disabled="busy||!usage" @click="copyLink(client)">复制链接</button><button :disabled="busy||!usage" @click="showQR(client)">显示二维码</button><button :disabled="busy||!usage" @click="reveal(client)">刷新订阅状态</button></div><p class="muted">{{formats.find(c=>c.id===client)?.note||'仅包含所选客户端支持的节点。'}} 链接包含凭据，请勿公开。</p><p v-if="checks[client]?.excluded_nodes" class="muted">已排除不兼容节点：{{checks[client].excluded_nodes}}</p></div><img v-if="qr&&qrClient===client" :src="qr" alt="所选客户端订阅二维码" width="180" height="180"></div></template></section>
<section v-if="selected&&!inactive" class="panel"><h3>此订阅的设备与客户端记录</h3><p class="muted">按所选订单的独立身份查询。未提供稳定设备标识时，无法保证物理设备去重。</p><div class="table-wrap"><table><thead><tr><th>客户端</th><th>名称</th><th>最近访问</th></tr></thead><tbody><tr v-for="(d,i) in devices" :key="d.id||i"><td>{{d.client_id||d.client||'未提供'}}</td><td>{{d.name||d.id}}</td><td>{{date(d.last_subscription_at||d.last_seen||d.updated_at)}}</td></tr></tbody></table></div><p v-if="!devices.length" class="empty">暂无客户端回传记录</p></section>
<RenewalDialog v-if="renewing&&selected" :request="request" :service="selected" @close="renewing=false" @payment="(order:Row)=>{renewing=false;emit('payment',order)}"/>
</template>
<style scoped>
.service-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:16px}.service-card{display:flex;flex-direction:column;padding:20px;border:1px solid #dce2ec;border-radius:12px;min-width:0}.service-card.selected{border-color:#377d74;background:#f5faf8}.service-card small{display:block;overflow-wrap:anywhere;margin:6px 0}.service-card h3{overflow-wrap:anywhere}.service-card .section-head{margin-bottom:8px;flex-wrap:wrap}.service-open{margin-top:auto;width:100%}.service-card small:last-of-type{margin-bottom:16px}.metrics{margin-bottom:18px}.pagination{margin-top:18px}.client-format{max-width:440px}.badge.deleted,.badge.invalid,.badge.expired,.badge.disabled,.badge.exhausted{color:#ad604e;background:#ffede8}@media(max-width:600px){.client-format{max-width:none}}
</style>
